--- index.html
+++ index.html
@@ -29,4 +29,67 @@
 </div>
 <div class="toast" id="toast" role="status"></div>
 <div class="modal-backdrop" id="modalBackdrop" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><div class="big-sigil" id="modalSigil">✦</div><div class="eyebrow" id="modalRarity">LEGENDARY</div><h2 id="modalTitle">Stand discovered</h2><p id="modalText"></p><div class="modal-actions"><button id="modalSell">Convert to echoes</button><button class="primary" id="modalEquip">Equip Stand</button></div></div></div>
 <script>
+const STANDS=[
+ {name:'Pocket Watcher',rarity:'Common',sigil:'◷',power:'A patient little omen',echoes:3},
+ {name:'Velvet Static',rarity:'Common',sigil:'〰',power:'The quiet between notes',echoes:3},
+ {name:'Paper Moon',rarity:'Common',sigil:'☾',power:'A dream folded twice',echoes:3},
+ {name:'Jade Comet',rarity:'Uncommon',sigil:'☄',power:'A streak across the night',echoes:6},
+ {name:'Glass Garden',rarity:'Uncommon',sigil:'❋',power:'Blooms where none should grow',echoes:6},
+ {name:'Velvet Voltage',rarity:'Uncommon',sigil:'ϟ',power:'Lightning in a velvet glove',echoes:6},
+ {name:'Neon Pilgrim',rarity:'Rare',sigil:'✣',power:'Walks the roads of tomorrow',echoes:12},
+ {name:'Crimson Rhapsody',rarity:'Rare',sigil:'♬',power:'A song with a pulse',echoes:12},
+ {name:'Mirage Engine',rarity:'Rare',sigil:'◈',power:'Reality, with a loose screw',echoes:12},
+ {name:'Solar Crown',rarity:'Epic',sigil:'♛',power:'Bends daylight to its will',echoes:25},
+ {name:'The Last Encore',rarity:'Epic',sigil:'✦',power:'The finale is never final',echoes:25},
+ {name:'STARFALL OVERDRIVE',rarity:'Legendary',sigil:'✹',power:'The universe holds its breath',echoes:60}
+];
+const RARITIES=['Common','Uncommon','Rare','Epic','Legendary'];
+const COLORS={Common:'#aaa3b5',Uncommon:'#75e2ad',Rare:'#70caff',Epic:'#c18bff',Legendary:'#ffcf70'};
+const initial={spins:0,echoes:0,level:0,owned:{},equipped:null,best:0,pity:0};
+let state={...initial};
+try{const saved=JSON.parse(localStorage.getItem('standbound-save'));if(saved&&typeof saved==='object')state={...initial,...saved,owned:saved.owned||{}}}catch{}
+let busy=false,auto=false,filter='all',autoTimer=null,toastTimer=null,lastStand=null;
+const $=id=>document.getElementById(id);
+function save(){try{localStorage.setItem('standbound-save',JSON.stringify(state))}catch{}}
+function rarityIndex(r){return RARITIES.indexOf(r)}
+function getStand(name){return STANDS.find(s=>s.name===name)}
+function notify(html){const t=$('toast');t.innerHTML=html;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
+function render(){
+ $('echoes').textContent=state.echoes.toLocaleString();$('spinCount').textContent=state.spins.toLocaleString();
+ const count=Object.keys(state.owned).filter(n=>state.owned[n]>0).length;$('discoverCount').textContent=`${count}/${STANDS.length}`;$('archiveCount').textContent=`${count}/${STANDS.length}`;
+ $('bestRarity').textContent=state.best?RARITIES[state.best]:'—';$('equippedName').textContent=state.equipped||'None';$('equippedName').title=state.equipped||'None';
+ $('pityLabel').textContent=`${state.pity} / 10`;$('pityBar').style.width=`${Math.min(100,state.pity*10)}%`;
+ const luck=1+state.level*.15;$('luckTag').textContent=`LUCK ×${luck.toFixed(2)}`;
+ const cost=25+state.level*35;$('upgradeInfo').textContent=`+15% rare luck · Level ${state.level}`;$('upgradeBtn').innerHTML=`✧ ${cost}`;$('upgradeBtn').disabled=state.echoes<cost;
+ renderCollection();
+}
+function renderCollection(){const grid=$('collectionGrid');grid.innerHTML='';const list=STANDS.filter(s=>(filter==='all'||s.rarity===filter)&&(state.owned[s.name]||0)>0);for(const s of list){const el=document.createElement('button');el.className=`stand-card${state.equipped===s.name?' equipped':''}`;el.style.setProperty('--rarity',COLORS[s.rarity]);el.setAttribute('aria-label',`${s.name}, ${s.rarity}. Tap to equip.`);el.innerHTML=`<div class="stand-card-top"><span class="rarity-dot"></span><span class="rarity-label">${s.rarity}</span></div><div class="card-sigil">${s.sigil}</div><h3>${s.name}</h3><p>${state.equipped===s.name?'✦ EQUIPPED':s.power}</p>${state.owned[s.name]>1?`<span class="card-count">×${state.owned[s.name]}</span>`:''}`;el.addEventListener('click',()=>equip(s));grid.append(el)}const remaining=Math.max(0,8-list.length);for(let i=0;i<remaining;i++){const blank=document.createElement('div');blank.className='empty-card';blank.textContent='Fate unknown';grid.append(blank)}}
+function equip(s){state.equipped=s.name;save();render();notify(`Equipped <b>${s.name}</b> · ${s.rarity}`)}
+function rarityRoll(){if(state.pity>=9)return 'Epic';const luck=1+state.level*.15;const weights=[54,26,13,5.5,1.5].map((w,i)=>w*Math.pow(luck,i));let n=Math.random()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<weights.length;i++){n-=weights[i];if(n<=0)return RARITIES[i]}return 'Common'}
+function tone(freq=440,duration=.11){if(!soundOn)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration);o.onended=()=>ctx.close()}catch{}}
+function summon(){if(busy)return;busy=true;$('rollBtn').disabled=true;$('stage').classList.add('is-rolling');$('resultName').innerHTML='<span class="result-placeholder">Fate is turning…</span>';$('resultMeta').textContent='THE THREADS ARE ALIGNING';tone(320,.15);setTimeout(()=>{
+ const rarity=rarityRoll(),choices=STANDS.filter(s=>s.rarity===rarity),stand=choices[Math.floor(Math.random()*choices.length)],wasOwned=(state.owned[stand.name]||0)>0;
+ state.spins++;state.pity=rarityIndex(rarity)>=3?0:state.pity+1;state.best=Math.max(state.best,rarityIndex(rarity));state.owned[stand.name]=(state.owned[stand.name]||0)+1;
+ if(wasOwned){state.echoes+=stand.echoes;tone(560,.2)}else{lastStand=stand;tone(rarity==='Legendary'?880:660,.3)}
+ $('stage').classList.remove('is-rolling');$('resultName').textContent=stand.name;$('resultName').style.color=COLORS[rarity];$('resultMeta').textContent=`${rarity.toUpperCase()} · ${stand.power.toUpperCase()}`;
+ $('standArt').style.filter=`drop-shadow(0 10px 28px ${COLORS[rarity]}88) hue-rotate(${rarityIndex(rarity)*34}deg)`;
+ $('standArt').style.transform=`scale(${1+rarityIndex(rarity)*.035})`;
+ save();render();busy=false;$('rollBtn').disabled=false;
+ if(wasOwned)notify(`Duplicate <b>${stand.name}</b> · +${stand.echoes} echoes`);else showDiscovery(stand);
+ },850)}
+function showDiscovery(s){$('modalSigil').textContent=s.sigil;$('modalSigil').style.color=COLORS[s.rarity];$('modalRarity').textContent=s.rarity.toUpperCase()+' STAND DISCOVERED';$('modalRarity').style.color=COLORS[s.rarity];$('modalTitle').textContent=s.name;$('modalText').textContent=`${s.power}. A new fate joins your archive. You can equip this Stand or convert it to ${s.echoes} echoes.`;$('modalBackdrop').classList.add('open')}
+function closeModal(){ $('modalBackdrop').classList.remove('open') }
+let soundOn=false;
+$('rollBtn').addEventListener('click',summon);
+$('autoBtn').addEventListener('click',()=>{auto=!auto;$('autoBtn').classList.toggle('active',auto);$('autoBtn').innerHTML=auto?'◉ &nbsp;STOP':'◉ &nbsp;AUTO';if(auto){autoTimer=setInterval(()=>{if(!busy&&!$('modalBackdrop').classList.contains('open'))summon()},1250);notify('Auto-spin <b>started</b>')}else{clearInterval(autoTimer);notify('Auto-spin <b>paused</b>')}});
+$('upgradeBtn').addEventListener('click',()=>{const cost=25+state.level*35;if(state.echoes<cost)return;state.echoes-=cost;state.level++;save();render();notify(`Fortune's Favor upgraded · <b>Luck ×${(1+state.level*.15).toFixed(2)}</b>`);tone(730,.24)});
+$('filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));renderCollection()});
+$('modalEquip').addEventListener('click',()=>{if(lastStand)state.equipped=lastStand.name;save();render();closeModal();notify(`<b>${lastStand.name}</b> equipped!`)});
+$('modalSell').addEventListener('click',()=>{if(!lastStand)return;state.owned[lastStand.name]=Math.max(0,(state.owned[lastStand.name]||1)-1);if(!state.owned[lastStand.name])delete state.owned[lastStand.name];state.echoes+=lastStand.echoes;save();render();closeModal();notify(`Converted <b>${lastStand.name}</b> · +${lastStand.echoes} echoes`)});
+$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
+$('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').style.color=soundOn?'var(--gold)':'#c5bdce';$('soundBtn').title=soundOn?'Mute sound':'Enable sound';if(soundOn)tone(640,.16)});
+render();
+</script>
+</body>
+</html>

